"""Root Langfuse trace for one Copilot v2 auto-analysis run.

Auto-analysis runs the same pydantic-ai machinery as an interactive turn, so its
spans reach Langfuse the same way: the ``Instrumentation`` capability emits
OpenTelemetry GenAI spans and Langfuse's span processor exports everything on
the tracer provider. Like the turn trace
(:mod:`rasa.builder.telemetry.langfuse_integration.copilot_v2_langfuse_telemetry`),
this module supplies only the parent those spans need.

It is a separate trace from an interactive turn, not a child of one. An analysis
sends the entire training log plus every changed file as instructions, so its
token profile differs from a chat turn's by orders of magnitude; sharing a trace
would corrupt per-turn cost and latency aggregates in both directions. The run
is also a distinct unit at the API boundary — it gets its own job id, which the
client subscribes to separately.

Separate does not mean unlinked. The session id is derived from the commit sha,
so the file change, the training failure, and the analysis of that failure group
together, and ``originating_job_id`` records which job's failure triggered this.

The span is opened by the job owner around the whole stream drain rather than
inside the streaming generator, for the same reason the turn trace is opened by
the web layer: a cancelled job unwinds ``async for`` without closing the
generator (Python leaves that to GC), so a context manager inside it would leak
the span on the commonest failure mode. In the caller, ``__exit__`` runs on
every path.

Token counts and per-request cost come from pydantic-ai's own instrumentation.
Nothing here writes them.
"""

from __future__ import annotations

import sys
from collections.abc import Iterator
from contextlib import contextmanager
from typing import TYPE_CHECKING, Any

import structlog
from opentelemetry import context as otel_context

from rasa.builder.telemetry.langfuse_integration.constants import (
    AUTO_ANALYSIS_TAG,
    COPILOT_V2_ANALYSIS_TRACE_NAME,
    COPILOT_V2_TRANSPORT_TAG,
    ERROR_TAG,
)
from rasa.builder.telemetry.langfuse_integration.langfuse_compat import with_langfuse
from rasa.builder.telemetry.langfuse_integration.shared import create_session_id

if TYPE_CHECKING:
    from rasa.builder.copilot.models import (
        CopilotOutput,
        InternalCopilotRequestChatMessage,
    )

structlogger = structlog.get_logger()

# The analysis job has no authenticated user: ``JobInfo`` carries an id, a
# status, and a commit sha, and nothing upstream threads an identity in. A
# training failure is not user-scoped anyway — the commit is what identifies it.
_NO_USER_ID = ""


class CopilotV2AnalysisTrace:
    """Accumulates one auto-analysis run's outcome and writes it to Langfuse.

    A single instance spans one analysis run. The job owner creates it, opens
    :meth:`observe` around the stream drain, and feeds every streamed output
    through :meth:`record_output`. On exit the accumulated outcome is written to
    the trace and the span closes.

    Every Langfuse interaction is best-effort: a telemetry failure is logged at
    debug and swallowed, because an analysis must never fail because tracing
    did.
    """

    def __init__(
        self,
        request_message: "InternalCopilotRequestChatMessage",
        job_id: str,
        commit_sha: str | None,
        originating_job_id: str | None,
        project_id: str | None,
    ) -> None:
        """Initialize the trace for one analysis run.

        Args:
            request_message: The internal request carrying the training error
                log and the changed files the analysis reasons over.
            job_id: Id of the analysis job itself.
            commit_sha: Sha of the commit whose training failed. ``None`` when
                the failure was not tied to a commit.
            originating_job_id: Id of the job whose failure triggered this
                analysis, or ``None`` when it was not supplied.
            project_id: The Hello Rasa project id, or ``None`` when unset in
                the environment.
        """
        self._request_message = request_message
        self._job_id = job_id
        self._commit_sha = commit_sha
        self._originating_job_id = originating_job_id
        self._project_id = project_id
        self._text_parts: list[str] = []
        self._error: dict[str, str] | None = None

    @contextmanager
    def observe(self) -> Iterator["CopilotV2AnalysisTrace"]:
        """Open the root span for the analysis, closing it on every exit path.

        Yields itself so the caller can feed the stream back in. When langfuse
        is not installed, or opening the span fails, the block still runs
        untraced — the caller sees no difference.
        """
        # This job is launched with ``app.add_task``, and ``asyncio.create_task``
        # copies the current contextvars — which is how OpenTelemetry propagates
        # a parent span. Without detaching, an analysis inherits whatever span
        # was active when the task was created and stops being its own trace.
        # Attaching an empty context makes this span a root by construction
        # rather than by luck about which callers happen to be untraced.
        #
        # Done outside the langfuse guard on purpose: the pydantic-ai spans are
        # emitted whether or not langfuse is installed, so a different
        # configured tracer provider would inherit just the same.
        context_token = otel_context.attach(otel_context.Context())
        try:
            with with_langfuse() as langfuse_module:
                if langfuse_module is None:
                    yield self
                    return
                try:
                    client = langfuse_module.get_client()
                    # ``start_as_current_span`` is a generator-based context
                    # manager, so calling it runs none of its body: creating the
                    # OTel span and serialising ``input`` both happen in
                    # ``__enter__``. Entering and exiting explicitly is what
                    # puts those steps under a guard — a ``with`` block here
                    # would leave the only half that can fail outside the
                    # ``try``.
                    span = client.start_as_current_span(
                        name=COPILOT_V2_ANALYSIS_TRACE_NAME,
                        input=self._trace_input(),
                    )
                    span.__enter__()
                except Exception as exc:
                    self._log_failure("open_span", exc)
                    yield self
                    return

                try:
                    yield self
                except Exception as exc:
                    # The job owner catches this and reports
                    # ``copilot_analysis_error``; record it first so the trace
                    # is tagged, then let it propagate unchanged.
                    self._record_exception(exc)
                    raise
                finally:
                    # Runs while the span is still current, which is what
                    # ``update_current_trace`` and ``update_current_span``
                    # resolve against.
                    self._write_outcome(client)
                    try:
                        # ``sys.exc_info()`` is whatever is propagating out (a
                        # triple of ``None`` on a clean exit), so the span
                        # records the failure exactly as ``with`` would —
                        # including ``CancelledError``, which the handler above
                        # lets past.
                        span.__exit__(*sys.exc_info())
                    except Exception as exc:
                        self._log_failure("close_span", exc)
        finally:
            otel_context.detach(context_token)

    def record_output(self, output: "CopilotOutput") -> None:
        """Fold one streamed analysis output into the accumulated text.

        Called once per streamed chunk, so it does no Langfuse I/O: text is
        appended to a single list joined at close. Non-text outputs (tool-call
        status payloads) are ignored — pydantic-ai's own tool spans carry them
        in more detail.

        Args:
            output: One output chunk, as yielded by the analysis stream.
        """
        try:
            # Imported here rather than at module scope: this package must stay
            # importable without the ``copilot-v2`` extra, and the models module
            # is cheap but sits behind the same runtime.
            from rasa.builder.copilot.models import CopilotTextContent

            if isinstance(output, CopilotTextContent):
                self._text_parts.append(output.content)
        except Exception as exc:
            self._log_failure("record_output", exc)

    def _record_exception(self, exc: Exception) -> None:
        """Record an escaping exception as the run's error, if none is set."""
        if self._error is not None:
            return
        # ``run_errors`` hard-imports pydantic-ai, so the import is local: this
        # package is otherwise installable without the ``copilot-v2`` extra, and
        # a telemetry module must not be the thing that breaks that. Reusing the
        # classifier keeps analysis failures in the same ``RunErrorCode``
        # vocabulary as chat failures, so error-rate metrics group both surfaces
        # on one attribute.
        try:
            from rasa.builder.copilot.pydantic_ai.run_errors import classify_run_error

            error_code = classify_run_error(exc).value
        except Exception:
            error_code = type(exc).__name__
        self._error = {"message": str(exc), "error_code": error_code}

    def _write_outcome(self, client: Any) -> None:
        """Write the accumulated outcome to the trace and the root span."""
        try:
            client.update_current_trace(
                session_id=self._session_id(),
                input=self._trace_input(),
                output=self._trace_output(),
                metadata=self._trace_metadata(),
                tags=self._trace_tags(),
            )
        except Exception as exc:
            self._log_failure("write_outcome", exc)

        if self._error is None:
            return

        # Guarded separately so a failure writing the payload above cannot also
        # cost the ERROR marking — that would lose exactly the traces worth
        # finding.
        try:
            client.update_current_span(
                level="ERROR",
                status_message=self._error["error_code"],
            )
        except Exception as exc:
            self._log_failure("mark_error", exc)

    def _session_id(self) -> str:
        """Build the Langfuse session id, keyed on the commit under analysis.

        The commit is what ties the file change, the failed training run, and
        this analysis together, and it is what a human has in hand when
        debugging — so repeated analyses of one commit group into one session.
        Falls back to the job id when the failure was not tied to a commit.
        The composite shape matches v1's and the v2 turn trace's so every
        Langfuse session id in the project reads the same way.
        """
        return create_session_id(
            hello_rasa_project_id=str(self._project_id),
            user_id=_NO_USER_ID,
            chat_id=self._commit_sha or self._job_id,
        )

    def _trace_input(self) -> dict[str, Any]:
        """Build the trace input: the training error log and the changed files.

        File *paths* only, not contents: the contents already reach Langfuse on
        the agent-run span (instrumentation records instructions), so repeating
        them here would double the payload of the largest field in the trace.
        """
        try:
            from rasa.builder.copilot.models import FileContent

            file_paths = [
                block.file_path
                for block in self._request_message.get_content_blocks_by_type(
                    FileContent
                )
            ]
        except Exception as exc:
            self._log_failure("trace_input", exc)
            file_paths = []

        return {
            "training_error_log": self._request_message.get_flattened_log_content(),
            "changed_file_paths": file_paths,
        }

    def _trace_output(self) -> dict[str, Any]:
        """Build the trace output from the accumulated analysis text."""
        output: dict[str, Any] = {"analysis": "".join(self._text_parts)}
        if self._error is not None:
            output["error"] = self._error
        return output

    def _response_category(self) -> str | None:
        """The request's response category, or ``None`` when it carries none.

        ``InternalCopilotRequestChatMessage`` validates the category to one of
        the two analysis categories, but the field is declared optional on the
        base message, so a missing value is representable. Telemetry reads it
        defensively rather than assuming the validator ran.
        """
        category = self._request_message.response_category
        return category.value if category is not None else None

    def _trace_metadata(self) -> dict[str, Any]:
        """Build the trace metadata: the ids that join this run to its cause."""
        return {
            "ids": {
                "job_id": self._job_id,
                "originating_job_id": self._originating_job_id,
                "commit_sha": self._commit_sha,
                "project_id": self._project_id,
            },
            "response_category": self._response_category(),
        }

    def _trace_tags(self) -> list[str]:
        """Build the trace tags: transport, surface, response category, errors."""
        tags = [COPILOT_V2_TRANSPORT_TAG, AUTO_ANALYSIS_TAG]
        if (category := self._response_category()) is not None:
            tags.append(category)
        if self._error is not None:
            tags.append(ERROR_TAG)
        return tags

    def _log_failure(self, step: str, exc: Exception) -> None:
        """Log a swallowed telemetry failure without the run's content."""
        structlogger.debug(
            f"copilot_v2_analysis_langfuse_telemetry.{step}.failed",
            job_id=self._job_id,
            error_type=type(exc).__name__,
        )
